(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03-t*0.15)*8+Math.cos(sy*0.025+t*0.2)*6;
  const w2y = Math.cos(sx*0.028+t*0.18)*8+Math.sin(sy*0.022-t*0.22)*6;
  const wx = sx+w2x, wy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.14,1.3],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*40,0.05,2.8],
    [200+Math.sin(t*0.25+6)*90,220+Math.cos(t*0.45+5)*70,0.11,1.6]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);}
  const act=aS/9,inh=iS/9;
  const bg1=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1))/2;
  const bg2=Math.sin((wx+wy)*0.12+t*2.5)*0.2+Math.sin((wx-wy)*0.1-t*2)*0.2;
  const bg3=Math.sin(wx*0.08+wy*0.06-t*1.5)*0.15+Math.cos(wx*0.07-wy*0.09+t*1.8)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.08+ang*2-t*2.0)+Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+sp1)*2.2);
  const r2=Math.tanh((act*0.8-inh+bg*0.2+sp2)*1.8);
  const cross=Math.tanh((r1*0.6+r2*0.4-r1*r2)*2.0);
  const c1=Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15)+Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.3;
  const c2=Math.tanh((Math.sin(wx*0.25+t*0.3)*Math.sin(wy*0.3-t*0.2)+Math.cos((wx-wy)*0.2+t*0.5)*0.3)*1.2)*0.15;
  const cell=c1+c2;
  const micro=Math.sin(wx*0.5+t*3)*Math.sin(wy*0.5-t*2.5)*0.05;
  const v=(cross*0.6+cell*0.25+micro)*0.5+0.5;
  const pal=[[6,12,52],[12,45,82],[18,85,105],[25,135,125],[85,175,140],[180,195,95],[225,175,65],[215,120,65],[185,70,75],[130,35,65],[70,18,48],[20,12,42],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(cross*Math.PI)*0.2;
  const edge=Math.abs(cross)>0.75?1.12:Math.abs(cross)>0.6?1.05:1.0;
  const hs=Math.sin(ang*2+t*0.3)*0.05;
  return[Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+hs*30))|0,Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+hs*15))|0,Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge-hs*20))|0];
}
